mapper.select:
WITH q AS ( SELECT websearch_to_tsquery('public.wsb_zhcfg', #{query}) AS ts_query, #{pattern} AS pattern ) SELECT (metadata->>'bookId')::bigint AS book_id, MAX( ts_rank_cd(to_tsvector('public.wsb_zhcfg', coalesce(content, '')), q.ts_query) + CASE WHEN content ILIKE q.pattern ESCAPE '\' THEN 0.50 ELSE 0 END + CASE WHEN metadata->>'title' ILIKE q.pattern ESCAPE '\' THEN 1.20 ELSE 0 END + CASE WHEN metadata->>'author' ILIKE q.pattern ESCAPE '\' THEN 1.00 ELSE 0 END + CASE WHEN metadata->>'keyword' ILIKE q.pattern ESCAPE '\' THEN 0.90 ELSE 0 END + CASE WHEN metadata->>'clcCategory' ILIKE q.pattern ESCAPE '\' THEN 0.75 ELSE 0 END + CASE WHEN metadata->>'clc' ILIKE q.pattern ESCAPE '\' THEN 0.70 ELSE 0 END
+ CASE WHEN content ILIKE #{queryPattern} ESCAPE '\' THEN 0.20 ELSE 0 END + CASE WHEN metadata->>'title' ILIKE #{queryPattern} ESCAPE '\' THEN 0.55 ELSE 0 END + CASE WHEN metadata->>'author' ILIKE #{queryPattern} ESCAPE '\' THEN 0.45 ELSE 0 END + CASE WHEN metadata->>'keyword' ILIKE #{queryPattern} ESCAPE '\' THEN 0.40 ELSE 0 END + CASE WHEN metadata->>'clcCategory' ILIKE #{queryPattern} ESCAPE '\' THEN 0.35 ELSE 0 END + CASE WHEN metadata->>'clc' ILIKE #{queryPattern} ESCAPE '\' THEN 0.30 ELSE 0 END
+ (coalesce(nullif(metadata->>'chunkWeight', ''), '1')::double precision * 0.05) ) AS rank_score FROM ${tableName}, q WHERE metadata->>'bookId' IS NOT NULL
AND (metadata->>'bookId')::bigint IN
#{bookId}
AND ( q.ts_query @@ to_tsvector('public.wsb_zhcfg', coalesce(content, '')) OR content ILIKE q.pattern ESCAPE '\' OR metadata->>'title' ILIKE q.pattern ESCAPE '\' OR metadata->>'author' ILIKE q.pattern ESCAPE '\' OR metadata->>'keyword' ILIKE q.pattern ESCAPE '\' OR metadata->>'clcCategory' ILIKE q.pattern ESCAPE '\' OR metadata->>'clc' ILIKE q.pattern ESCAPE '\'
OR content ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'title' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'author' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'keyword' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'clcCategory' ILIKE #{queryPattern} ESCAPE '\' OR metadata->>'clc' ILIKE #{queryPattern} ESCAPE '\'
) GROUP BY metadata->>'bookId' ORDER BY rank_score DESC LIMIT #{limit}

WITH source_chunks AS (
    SELECT embedding,
           coalesce(nullif(metadata->>'chunkWeight', ''), '1')::double precision AS chunk_weight
    FROM ${tableName}
    WHERE (metadata->>'bookId')::bigint = #{bookId}
),
chunk_knn AS (
    SELECT (candidate.metadata->>'bookId')::bigint AS book_id,
           (1 - (candidate.embedding <=> source.embedding))
           * (1 + (coalesce(nullif(candidate.metadata->>'chunkWeight', ''), '1')::double precision - 1) * 0.10)
           * (1 + (source.chunk_weight - 1) * 0.05) AS rank_score
    FROM source_chunks source
    CROSS JOIN LATERAL (
        SELECT metadata, embedding
        FROM ${tableName}
        WHERE metadata->>'bookId' IS NOT NULL
          AND (metadata->>'bookId')::bigint <> #{bookId}
        ORDER BY embedding <=> source.embedding
        LIMIT #{candidateLimit}
    ) candidate
)
SELECT book_id,
       MAX(rank_score) AS rank_score
FROM chunk_knn
GROUP BY book_id
ORDER BY rank_score DESC, book_id ASC
LIMIT #{limit}
